import { useState, useRef, useEffect } from 'react'
import { connect } from 'react-redux'
import { useHistory, useParams } from 'react-router'
import { Container, InnerForm, Button } from '../../../../../components'
import StepsHeader from '../../../../../components/StepsHeader'
import { BottomActionContainerStyle } from '../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../lang'
import propertyActions from '../../../../../redux/property/actions'
import { PolicyContextProvider } from '../../../Policy/context'
import { PROPERTY_LANG } from '../../lang'
import {
  categoryFormData,
  mapCategoryApiData,
  questionFormData,
  mapQuestionApiData,
} from '../constants'
import useDraftApi from '../hooks/useDraftApi'
import { PropertyDataStyle } from './index.style'
import { PROPERTY_PROTECTION } from '../../../../../constants/pkgCode'

function PropertyData(props) {
  const {
    getPropertyProvince,
    provincesLoader,
    provinces,
    getPropertyCities,
    citiesLoader,
    propertyCities,
    getPropertyOccupation,
    propertyOccupation,
  } = props

  const history = useHistory()
  const { draftId } = useParams()

  // Ref property
  const categoryFormRef = useRef(null)
  const questionFormRef = useRef(null)
  const cityFieldRef = useRef(null)
  const buildingUseFieldRef = useRef(null)
  const [draftPolicyDetails, setDraftPolicyDetails] = useState({})

  const { isGetDraftLoader, isSaveLoader, handleSaveToDraft } = useDraftApi({
    draftId: draftId,
    onGetDraftDetailSuccess: (data) => {
      setDraftPolicyDetails(data?.policy_details)
    },
    onSaveSuccess: ({ draftId }) => {
      history.push(`/property/property-protection/2/form/${draftId}`)
    },
  })

  useEffect(() => {
    // fetch on first render
    getPropertyProvince()
    getPropertyOccupation()
  }, [getPropertyProvince, getPropertyOccupation])

  useEffect(() => {
    if (draftPolicyDetails.province_code) {
      getPropertyCities(draftPolicyDetails.province_code)
    }
  }, [draftPolicyDetails.province_code, getPropertyCities])

  const handleCategoryFormChange = (value) => {
    if (value.province_code) {
      // Reset city selection & options on province change
      cityFieldRef.current.resetModalState()
      setDraftPolicyDetails({ ...draftPolicyDetails, ...value })
    }
    if (value.occupation_name) {
      // Reset building use selection & options on building category change
      buildingUseFieldRef.current.resetModalState()
      setDraftPolicyDetails({
        ...draftPolicyDetails,
        property_data: { ...draftPolicyDetails.property_data, ...value },
      })
    }
    if (value.occupation_code) {
      // Update draftPolicyDetails for questionnaire check
      setDraftPolicyDetails({
        ...draftPolicyDetails,
        property_data: { ...draftPolicyDetails.property_data, ...value },
      })
    }
  }

  const handleSubmitForm = async (e) => {
    // here we validate the form and its details
    const validatedPropertyData = await categoryFormRef.current.handleSubmit(e)
    const validatedQuestionData = await questionFormRef.current.handleSubmit(e) // verify data only, no need to read the value
    // here we submit the form data
    if (
      validatedPropertyData &&
      !validatedPropertyData.error &&
      validatedQuestionData &&
      !validatedQuestionData.error
    ) {
      const finalData = {
        product_code: PROPERTY_PROTECTION,
        ...draftPolicyDetails,
        ...mapCategoryApiData(validatedPropertyData, draftPolicyDetails, {
          provinces,
          propertyCities,
          propertyOccupation,
        }),
        ...mapQuestionApiData(validatedQuestionData),
      }
      // store to localstorage so that form prefilled on back
      handleSaveToDraft(finalData, 'property_details', 'property_ownership', true)
    }
  }

  const getCategoryFormData = () => {
    const form = categoryFormData(draftPolicyDetails, {
      provinces,
      propertyCities,
      propertyOccupation,
    })
    form.fields[1].ref = cityFieldRef
    form.fields[5].ref = buildingUseFieldRef
    return form
  }

  return (
    <Container
      title={PROPERTY_LANG.propertyInsurance}
      loader={provincesLoader || citiesLoader || isGetDraftLoader || isSaveLoader}
      hideBottomTabs
      showCloseIcon
      onClose={() => history.push('/dashboard')}
      onBackClick={() => history.push('/dashboard')}
    >
      <PropertyDataStyle>
        <StepsHeader
          current="1"
          totalSteps="6"
          leftText={PROPERTY_LANG.dataChecking}
          className="steps-header"
        />
        <div className="property-form-data">
          <InnerForm
            formData={getCategoryFormData()}
            onChangeSelect={handleCategoryFormChange}
            ref={categoryFormRef}
          />
          <InnerForm formData={questionFormData(draftPolicyDetails)} ref={questionFormRef} />
        </div>
        <BottomActionContainerStyle padding="0">
          <Button className="button-margin" onClick={handleSubmitForm} id="propertyStepSubmit_1">
            {LANG_STRINGS.next}
          </Button>
        </BottomActionContainerStyle>
      </PropertyDataStyle>
    </Container>
  )
}

function WrappedPropertyData(props) {
  return (
    <PolicyContextProvider>
      <PropertyData {...props} />
    </PolicyContextProvider>
  )
}

const { getPropertyProvince, getPropertyCities, getPropertyOccupation } = propertyActions

export default connect(
  (state) => ({
    provinces: state.Property.provinces,
    propertyCities: state.Property.propertyCities,
    propertyOccupation: state.Property.propertyOccupation,
    provincesLoader: state.Loading.GET_PROPERTY_PROVINCE,
    citiesLoader: state.Loading.GET_PROPERTY_CITIES,
  }),
  {
    getPropertyProvince,
    getPropertyCities,
    getPropertyOccupation,
  }
)(WrappedPropertyData)
